function createPeer(member,initiator){
 const pc=new RTCPeerConnection({iceServers:state.iceServers});const tile=document.createElement('article');tile.className='tile remote';tile.dataset.name=member.name;const avatar=document.createElement('div');avatar.className='avatar';avatar.textContent=member.name[0];const video=document.createElement('video');video.autoplay=true;video.playsInline=true;video.muted=true;video.style.transform=state.you.role==='teacher'?'scaleX(-1)':'none';video.hidden=true;const audio=document.createElement('audio');audio.autoplay=true;const label=document.createElement('div');label.className='tilelabel';label.textContent=member.name;const info=document.createElement('div');info.className='peerstate';info.textContent='Conectando…';tile.append(avatar,video,audio,label,info);$('tiles').append(tile);
 const retry=document.createElement('button');retry.type='button';retry.className='remote-video-retry';retry.textContent='Mostrar câmera';retry.hidden=true;tile.append(retry);
 const screenAudio=document.createElement('audio');screenAudio.autoplay=true;const soundRetry=document.createElement('button');soundRetry.type='button';soundRetry.className='screen-audio-retry';soundRetry.textContent='Ouvir som compartilhado';soundRetry.hidden=true;tile.append(screenAudio);document.querySelector('.screen-actions').prepend(soundRetry);const playScreenAudio=()=>{if(!screenAudio.srcObject||screenAudio.muted||pc.connectionState==='closed')return;screenAudio.play().then(()=>{soundRetry.hidden=true}).catch(()=>{soundRetry.hidden=false;});};soundRetry.onclick=playScreenAudio;
 const p={pc,tile,video,avatar,audio,retry,screenAudio,soundRetry,playScreenAudio,member,screen:new MediaStream(),candidates:[],ready:Promise.resolve()};
 const playCamera=()=>{if(!video.srcObject||pc.connectionState==='closed')return;video.play().then(()=>{retry.hidden=true}).catch(error=>{if(error.name==='AbortError')return;retry.hidden=false;info.textContent='Clique para mostrar a câmera';});};retry.onclick=playCamera;video.addEventListener('loadeddata',playCamera);video.addEventListener('canplay',playCamera);p.playCamera=playCamera;peers.set(member.id,p);
 if(initiator){for(const kind of ['audio','video','video','audio'])pc.addTransceiver(kind,{direction:'sendrecv'});bindTracks(p)}
 pc.onicecandidate=e=>{if(e.candidate)api('signal',{to:member.id,type:'ice',payload:e.candidate.toJSON()}).catch(()=>{})};
 pc.ontrack=e=>{const index=pc.getTransceivers().indexOf(e.transceiver);const s=new MediaStream([e.track]);if(index===0){audio.srcObject=s;audio.play().catch(()=>toast('Clique na sala para permitir o áudio do aluno.'))}else if(index===1){video.srcObject=s;e.track.addEventListener('unmute',playCamera);playCamera()}else if(index===3){screenAudio.srcObject=s;screenAudio.muted=!p.member.media?.screen;e.track.addEventListener('unmute',playScreenAudio);playScreenAudio()}else if(index===2){p.screen=s;if(p.member.media?.screen&&!screenStream){$('screenVideo').srcObject=s;$('screenStage').hidden=false;$('screenOwner').textContent=p.member.name+' está compartilhando';$('stopScreen').hidden=true}}};
 pc.onconnectionstatechange=()=>{info.textContent=pc.connectionState==='connected'?'Conectado':pc.connectionState==='failed'?'Falha de conexão':pc.connectionState==='disconnected'?'Reconectando…':'Conectando…';if(pc.connectionState==='failed')$('mediaStatus').textContent='Falha na chamada com '+member.name+'. Redes externas podem exigir servidor TURN.'};return p;
}
async function bindTracks(p){await Promise.all(p.pc.getTransceivers().map((t,i)=>{t.direction='sendrecv';return t.sender.replaceTrack(localTracks()[i]||null)}))}
async function updateTracks(){await Promise.all([...peers.values()].map(bindTracks));if(state?.you.status==='accepted'&&!state.ended)await api('media',{camera:!!cameraStream,microphone:!!audioStream,screen:!!screenStream})}
async function offer(p,to){await bindTracks(p);await p.pc.setLocalDescription(await p.pc.createOffer());await api('signal',{to,type:'offer',payload:p.pc.localDescription.toJSON()})}
async function signal(data){let p=peers.get(data.from);const member=state.members.find(m=>m.id===data.from);if(!member||data.toGeneration!==state.you.generation||data.fromGeneration!==member.generation)return;if(!p)p=createPeer(member,false);
 if(data.type==='ice'){if(p.pc.remoteDescription)await p.pc.addIceCandidate(data.payload);else p.candidates.push(data.payload);return}
 if(data.type==='offer'){await p.pc.setRemoteDescription(data.payload);await bindTracks(p);await p.pc.setLocalDescription(await p.pc.createAnswer());await api('signal',{to:data.from,type:'answer',payload:p.pc.localDescription.toJSON()})}
 else {if(p.pc.signalingState!=='have-local-offer')return;await p.pc.setRemoteDescription(data.payload);}
 for(const c of p.candidates.splice(0))await p.pc.addIceCandidate(c);
}
async function poll(){if(finished)return;try{const result=await api('events?since='+cursor);state=result.state;renderState();if(state.incremental&&state.you.status==='accepted'){if(!transcriptsLoaded)await loadLatestTranscripts();const page=await api('transcripts?after='+transcriptCursor);for(const t of page.records)addRecord(t);if(BigInt(page.cursor)>BigInt(transcriptCursor))transcriptCursor=page.cursor;}for(const event of result.events)if(event.type==='signal'&&!finished){try{await signal(event.data)}catch(e){$('mediaStatus').textContent='Falha ao conectar um participante: '+e.message}}cursor=result.cursor;if(!state.ended&&!state.ending)$('roomStatus').textContent=state.you.status==='pending'?'Aguardando aprovação':state.you.status==='accepted'?'Sala conectada':'Entrada recusada';}catch(e){$('roomStatus').textContent='Conexão interrompida';$('mediaStatus').textContent=e.message+' As falas locais aguardam reenvio.';}for(const [key,b] of pendingWrites)sendRecord(b,key);if(!finished)pollTimer=setTimeout(poll,state?.incremental?(document.hidden?6000:1500):1000)}
function mediaError(e){return ({NotAllowedError:'Permita o acesso nas configurações do navegador.',NotFoundError:'Dispositivo não encontrado.',NotReadableError:'Dispositivo ocupado. Feche outros aplicativos que estejam usando-o.'})[e.name]||e.message}
