async function stopScreen(){if(!screenStream)return;screenStream.getTracks().forEach(t=>t.stop());screenStream=null;$('shareAudioStatus').textContent='';$('screenStage').hidden=true;$('screenVideo').srcObject=null;window.meetingUI.controlLabel('share','Compartilhar tela');await updateTracks().catch(()=>{})}
